module keypress_generator(
    input clk,    
    input reset,  
    output reg [9:0] keypress  
);
reg [31:0] counter;
    reg [31:0] index;
    reg [31:0] keypress_array [100:0];
    initial begin
        counter = 0;
        index = 0;
    end
    always @(posedge clk) begin
        if (reset) begin
            counter = 0;
            index = 0;
        end else begin
            if (counter == 20) begin
                counter = 0;
                index = index + 1;
            end
            if (index == 100) begin
                index = 0;
            end
            keypress = keypress_array[index];
        end
    end
endmodule

