logic              i0_valid_next, i0_ready_next;
logic              t0_valid_next, t0_ready_next;

always_ff @(posedge clk, negedge reset_n) begin
	if (!reset_n) begin
		s <= S0;
		i0_valid <= 1'b0;
		t0_valid <= 1'b0;
	end else begin
		s <= s_next;
		i0_valid <= i0_valid_next;
		t0_valid <= t0_valid_next;
	end
end

always_comb begin
	s_next = s;
	i0_valid_next = 1'b0;
	t0_valid_next = 1'b0;
	case (s)
		S0: begin
			if (t0_valid) begin
				s_next = S1;
				i0_valid_next = 1'b1;
				t0_valid_next = 1'b1;
			end
		end
		S1: begin
			if (t0_valid && i0_ready) begin
				s_next = S2;
				i0_valid_next = 1'b1;
				t0_valid_next = 1'b1;
			end
		end
		S2: begin
			if (t0_valid && i0_ready) begin
				s_next = S3;
				i0_valid_next = 1'b1;
				t0_valid_next = 1'b1;
