module im2_control(
input wire i_CLK_CPU,
input wire i_reset,
input wire i_m1_n,
input wire i_mreq_n,
input wire i_iorq_n,
input wire i_rfsh_n,
input wire [7:0] i_cpu_d,
output wire o_reti_decode,
output wire o_reti_seen
);
parameter S_0 = 4'b0000;
parameter S_ED_T4 = 4'b0001;
parameter S_4D_T4 = 4'b0010;
parameter S_CB_T4 = 4'b0011;
reg [3:0] state;
reg [7:0] ifetch_d;
reg ifetch;
reg ifetch_cancel;
wire [7:0] cpu_opcode;
assign cpu_opcode = ifetch_d[7:0];
assign o_reti_decode = (state == S_ED_T4) | (state == S_4D_T4) | (state == S_CB_T4);
assign o_reti_seen = (state == S_ED_T4) | (state == S_4D_T4) | (state == S_CB_T4);
always @(posedge i_CLK_CPU or posedge i_reset) begin
	if (i_reset) begin
		state <= S_0;
		ifetch_d <= 8'b00000000;
		ifetch <= 1'b0;
		ifetch_cancel <= 1'b0;
	end else begin
		ifetch_d <= cpu_opcode;
		ifetch <= i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;
		ifetch_cancel <= i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n;
		case (state)
		S_0: begin
			ifetch_d <= 8'b00000000;
			ifetch <= 1'b0;
			ifetch_cancel <= 1'b0;
			if (i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n) begin
				state <= S_ED_T4;
			end
		end
		S_ED_T4: begin
			ifetch_d <= 8'b00000000;
			ifetch <= 1'b0;
			ifetch_cancel <= 1'b0;
			if (i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n) begin
				if (cpu_opcode == 8'b00000001) begin
					state <= S_4D_T4;
				end else if (cpu_opcode == 8'b00000010) begin
					state <= S_CB_T4;
				end
			end
		end
		S_4D_T4: begin
			ifetch_d <= 8'b00000000;
			ifetch <= 1'b0;
			ifetch_cancel <= 1'b0;
			if (i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n) begin
				if (cpu_opcode == 8'b00000001) begin
					state <= S_4D_T4;
				end else if (cpu_opcode == 8'b00000010) begin
					state <= S_CB_T4;
				end
			end
		end
		S_CB_T4: begin
			ifetch_d <= 8'b00000000;
			ifetch <= 1'b0;
			ifetch_cancel <= 1'b0;
			if (i_m1_n & i_mreq_n & i_iorq_n & i_rfsh_n) begin
				if (cpu_opcode == 8'b00000001) begin
					state <= S_4D_T4;
				end else if (cpu_opcode == 8'b00000010) begin
					state <= S_CB_T4;
				end
			end
		end
		default: begin
			state <= S_0;
			ifetch_d <= 8'b00000000;
			ifetch <= 1'b0;
			ifetch_cancel <= 1'b0;
		end
		endcase
	end
end
endmodule

