module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

    reg [1:0] state;
    reg [N-1:0] data_p1, data_p2;

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= {N{1'b0}};
            data_p2 <= {N{1'b0}};
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid) begin
                        data_p1 <= s_data;
                        data_p2 <= s_data;
                        state <= ONE;
                    end
                end
                ONE: begin
                    if (s_valid) begin
                        data_p1 <= s_data;
                        data_p2 <= s_data;
                    end
                    if (s_ready) begin
                        data_p1 <= data_p2;
                        state <= TWO;
                    end
                end
                TWO: begin
                    if (s_valid) begin
                        data_p1 <= s_data;
                        data_p2 <= s_data;
                    end
                    if (s_ready) begin
                        data_p1 <= data_p2;
                        state <= ZERO;
                    end
                    if (m_ready) begin
                        m_data <= data_p1;
                        m_valid <= 1'b1;
                    end else begin
                        m_data <= {N{1'b0}};
                        m_valid <= 1'b0;
                    end
                end
                default: begin
                    state <= ZERO;
                    data_p1 <= {N{1'b0}};
                    data_p2 <= {N{1'b0}};
                end
            endcase
        end
    end

endmodule

