input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
);
parameter [31:0] RESET=4'b0000;
parameter [31:0] IDLE=4'b0001;
parameter [31:0] RUNNING=4'b0010;
parameter [31:0] COMPLETE=4'b0011;
reg [31:0] current_state;
reg [31:0] next_state;
assign done = (current_state == COMPLETE) ? 1'b1 : 1'b0;
assign WDATA = (current_state == RUNNING) ? data : 32'b0;
assign WSTRB = (current_state == RUNNING) ? 4'b1111 : 4'b0000;
assign WVALID = (current_state == RUNNING) ? 1'b1 : 1'b0;
always @(posedge clk or negedge resetn) begin
    if(!resetn) begin
        current_state <= RESET;
    end else begin
        current_state <= next_state;
    end
end
always @(*) begin
    case(current_state)
    RESET: begin
        next_state <= IDLE;
    end
    IDLE: begin
        if(go) begin
            next_state <= RUNNING;
        end else begin
            next_state <= IDLE;
        end
    end
    RUNNING: begin
        if(WREADY) begin
            next_state <= COMPLETE;
        end else begin
            next_state <= RUNNING;
        end
    end
    COMPLETE: begin
        next_state <= IDLE;
    end
    default: begin
        next_state <= IDLE;
    end
    endcase
end
endmodule

