module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0;
reg [AW-1:0] cached_addr1;
reg [DW-1:0] cached_data0;
reg [DW-1:0] cached_data1;
reg [21:0] subaddr;
reg good;
reg hit0, hit1;

always @* begin
    addr_req = addr;
    if (DW == 8) begin
        addr_req[AW-1:12] = 0;
    end else if (DW == 16) begin
        addr_req[AW-1:14] = 0;
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        sdram_addr <= 0;
        data_ok <= 0;
        req <= 0;
        cached_addr0 <= 0;
        cached_addr1 <= 0;
        cached_data0 <= 0;
        cached_data1 <= 0;
        subaddr <= 0;
        good <= 0;
        hit0 <= 0;
        hit1 <= 0;
    end else begin
        if (clr) begin
            sdram_addr <= 0;
            data_ok <= 0;
            req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
            hit0 <= 0;
            hit1 <= 0;
        end else begin
            if (addr_ok) begin
                if (hit0) begin
                    sdram_addr <= cached_addr0;
                    data_ok <= 1;
                    req <= 0;
                end else if (hit1) begin
                    sdram_addr <= cached_addr1;
                    data_ok <= 1;
                    req <= 0;
                end else begin
                    sdram_addr <= addr_req;
                    data_ok <= 0;
                    req <= 1;
                end
            end else begin
                sdram_addr <= 0;
                data_ok <= 0;
                req <= 0;
            end
            if (we) begin
                if (addr_ok) begin
                    if (hit0) begin
                        cached_data0 <= din;
                        good <= 1;
                    end else if (hit1) begin
                        cached_data1 <= din;
                        good <= 1;
                    end else begin
                        cached_data0 <= din;
                        cached_data1 <= din;
                        good <= 0;
                    end
                end
            end
            if (addr_ok) begin
                if (addr_req[AW-1:12] == cached_addr0[AW-1:12]) begin
                    hit0 <= 1;
                    hit1 <= 0;
                end else if (addr_req[AW-1:14] == cached_addr1[AW-1:14]) begin
                    hit0 <= 0;
                    hit1 <= 1;
                end else begin
                    hit0 <= 0;
                    hit1 <= 0;
                end
            end
            subaddr <= addr_req[AW-1:12];
        end
    end
end

endmodule

