module io_ps2_keyboard(
input wire clk,
input wire kbd_clk,
input wire kbd_dat,
output reg interrupt,
output reg [7:0] scanCode
);
parameter CLK_SPEED = 100000000;
reg [31:0] shift_reg;
reg clk_filter;
reg timeout;
reg [31:0] bitsCount;
reg [31:0] debounce_const = 32'h00000000;
reg [31:0] timeout_const = 32'h00000000;
assign interrupt = (bitsCount == 8'b11111111) && (shift_reg[7] == 1'b0);
assign scanCode = shift_reg[7:0];
always @(posedge clk) begin
    if(timeout) begin
        timeout <= 0;
        bitsCount <= 0;
        shift_reg <= 0;
    end else begin
        if(kbd_clk) begin
            if(!clk_filter) begin
                if(!timeout) begin
                    if(!debounce_const) begin
                        shift_reg <= {shift_reg[6:0], kbd_dat};
                        bitsCount <= bitsCount + 1;
                        debounce_const <= 32'h00000000;
                    end else begin
                        debounce_const <= debounce_const - 1;
                    end
                end else begin
                    timeout <= 1;
                end
            end else begin
                clk_filter <= 0;
            end
        end else begin
            clk_filter <= 1;
        end
    end
end
endmodule

