module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
);
parameter [10:0] H_ACTIVE = 1280;
parameter [10:0] V_ACTIVE = 720;
parameter [10:0] H_FRONT_PORCH = 10;
parameter [10:0] H_BACK_PORCH = 10;
parameter [10:0] H_SYNC_WIDTH = 10;
parameter [10:0] V_FRONT_PORCH = 10;
parameter [10:0] V_BACK_PORCH = 10;
parameter [10:0] V_SYNC_WIDTH = 10;
parameter [10:0] TOTAL_PIXELS = H_ACTIVE * V_ACTIVE;
parameter [10:0] H_TOTAL_PIXELS = H_ACTIVE + H_FRONT_PORCH + H_BACK_PORCH;
parameter [10:0] V_TOTAL_PIXELS = V_ACTIVE + V_FRONT_PORCH + V_BACK_PORCH;
parameter [10:0] H_COUNTER_WIDTH = 10;
parameter [10:0] V_COUNTER_WIDTH = 10;
parameter [10:0] X_COUNTER_WIDTH = 10;
parameter [10:0] Y_COUNTER_WIDTH = 10;
parameter [10:0] H_COUNTER_RESET = H_TOTAL_PIXELS - 1;
parameter [10:0] V_COUNTER_RESET = V_TOTAL_PIXELS - 1;
parameter [10:0] X_COUNTER_RESET = H_ACTIVE - 1;
parameter [10:0] Y_COUNTER_RESET = V_ACTIVE - 1;
reg [H_COUNTER_WIDTH:0] h_counter;
reg [V_COUNTER_WIDTH:0] v_counter;
reg [X_COUNTER_WIDTH:0] x_counter;
reg [Y_COUNTER_WIDTH:0] y_counter;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
assign H_SYNC = h_counter == H_TOTAL_PIXELS - 1;
assign V_SYNC = v_counter == V_TOTAL_PIXELS - 1;
assign DISP_EN = h_counter < H_ACTIVE && v_counter < V_ACTIVE;
always @(posedge RST, posedge CLK) begin
    if (RST) begin
        h_counter <= H_COUNTER_RESET;
        v_counter <= V_COUNTER_RESET;
        x_counter <= X_COUNTER_RESET;
        y_counter <= Y_COUNTER_RESET;
    end else begin
        if (h_counter == H_TOTAL_PIXELS - 1) begin
            h_counter <= 0;
            v_counter <= v_counter + 1;
        end else begin
            h_counter <= h_counter + 1;
        end
        if (v_counter == V_TOTAL_PIXELS - 1) begin
            v_counter <= 0;
            x_counter <= x_counter + 1;
        end else begin
            v_counter <= v_counter + 1;
        end
        if (x_counter == H_ACTIVE - 1) begin
            x_counter <= 0;
            y_counter <= y_counter + 1;
        end else begin
            x_counter <= x_counter + 1;
        end
    end
end
endmodule

