module tx_add_preamble(
input wire clk,
input wire data_valid_in,
input wire [7:0] data_in,
output reg data_valid_out,
output reg [7:0] data_out
);
reg [63:0] delay_data;
reg [7:0] delay_data_valid;
always @(posedge clk) begin
    if(data_valid_in) begin
        delay_data[63:56] <= delay_data[63:56];
        delay_data[55:48] <= delay_data[55:48];
        delay_data[47:40] <= delay_data[47:40];
        delay_data[39:32] <= delay_data[39:32];
        delay_data[31:24] <= delay_data[31:24];
        delay_data[23:16] <= delay_data[23:16];
        delay_data[15:8] <= delay_data[15:8];
        delay_data[7:0] <= data_in;
        delay_data_valid[7:0] <= {delay_data_valid[6:0], 1'b1};
    end else begin
        delay_data[63:56] <= delay_data[63:56];
        delay_data[55:48] <= delay_data[55:48];
        delay_data[47:40] <= delay_data[47:40];
        delay_data[39:32] <= delay_data[39:32];
        delay_data[31:24] <= delay_data[31:24];
        delay_data[23:16] <= delay_data[23:16];
        delay_data[15:8] <= delay_data[15:8];
        delay_data[7:0] <= 8'b00000000;
        delay_data_valid[7:0] <= {delay_data_valid[6:0], 1'b0};
    end
end
always @(posedge clk) begin
    if(data_valid_in) begin
        data_valid_out <= 1'b1;
        data_out <= 8'b01010101;
    end else if(delay_data_valid[7]) begin
        data_valid_out <= 1'b1;
        data_out <= delay_data[7:0];
    end else if(delay_data_valid[6]) begin
        data_valid_out <= 1'b1;
        data_out <= 8'b11010101;
    end else begin
        data_valid_out <= 1'b0;
        data_out <= 8'b00000000;
    end
end
endmodule

