module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

    reg [1:0] state;
    reg [N-1:0] data_p1, data_p2;
    reg load_p1, load_p2, load_p1_from_p2;

    assign s_ready = state == ZERO || state == ONE;
    assign m_data  = state == TWO ? data_p1 : data_p2;
    assign m_valid = state == TWO;

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 0;
            data_p2 <= 0;
            load_p1 <= 0;
            load_p2 <= 0;
            load_p1_from_p2 <= 0;
        end else begin
            if (s_valid && m_ready) begin
                if (state == ZERO) begin
                    data_p1 <= s_data;
                    load_p1 <= 1;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                    state <= ONE;
                end else if (state == ONE) begin
                    data_p2 <= s_data;
                    load_p1 <= 0;
                    load_p2 <= 1;
                    load_p1_from_p2 <= 0;
                    state <= TWO;
                end else if (state == TWO) begin
                    data_p1 <= data_p2;
                    load_p1 <= 0;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 1;
                    state <= ZERO;
                end
            end
        end
    end
endmodule

