module pipelined_multiplier (a, b, clk, pdt);
input [size-1 : 0] a;
input [size-1 : 0] b;
input clk;
output [2*size-1 : 0] pdt;
parameter size = 16;
parameter level = 4;
reg [2*size-1 : 0] pdt_int [0 : level-1];
reg [size-1 : 0] a_int, b_int;
always @(posedge clk) begin
    a_int <= a;
    b_int <= b;
    for (integer i = 0; i < level-1; i = i + 1) begin
        pdt_int[i] <= pdt_int[i+1];
    end
    pdt_int[level-1] <= a_int * b_int;
end
assign pdt = pdt_int[level-1];
endmodule

