module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata_mux [0:3];
  reg [3*NBITS-1:0] rdata_mux_out [0:3];
  reg [3*NBITS-1:0] rdata_mux_out2;
  assign hrdata = rdata_mux_out2;
  always @(posedge hclk) begin
    if (hresetn == 1'b0) begin
      rdata_mux[0] <= 0;
      rdata_mux[1] <= 0;
      rdata_mux[2] <= 0;
      rdata_mux[3] <= 0;
    end else begin
      if (valid_rd == 1'b1) begin
        rdata_mux[0] <= rdata[0];
        rdata_mux[1] <= rdata[1];
        rdata_mux[2] <= rdata[2];
        rdata_mux[3] <= rdata[3];
      end
    end
  end
  assign rdata_mux_out[0] = rdata_mux[0] | rdata_mux[1];
  assign rdata_mux_out[1] = rdata_mux[2] | rdata_mux[3];
  assign rdata_mux_out2 = rdata_mux_out[0] | rdata_mux_out[1];
endmodule

