module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [3:0] counter;
    reg [7:0] dout_parallel_reg;
    reg dout_valid_reg;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dout_parallel <= 0;
            dout_valid <= 0;
            counter <= 0;
            dout_parallel_reg <= 0;
            dout_valid_reg <= 0;
        end else begin
            if (din_valid) begin
                dout_parallel_reg <= {dout_parallel_reg[6:0], din_serial};
                counter <= counter + 1;
                if (counter == 8) begin
                    dout_valid_reg <= 1;
                    counter <= 0;
                    dout_parallel <= dout_parallel_reg;
                    dout_valid <= dout_valid_reg;
                end
            end else begin
                dout_valid_reg <= 0;
                counter <= 0;
                dout_parallel <= 0;
                dout_valid <= dout_valid_reg;
            end
        end
    end
endmodule

