module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 9600;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  reg [31:0] clk_cnt = 0;
  reg [31:0] tx_cnt = 0;
  reg [7:0] tx_data = 0;
  reg tx_flag = 0;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= 0;
      tx_cnt <= 0;
      tx_data <= 0;
      clk_cnt <= 0;
    end else begin
      if (tx_flag) begin
        if (tx_cnt == 8) begin
          tx_flag <= 0;
          tx_cnt <= 0;
          tx_data <= 0;
        end else begin
          tx_cnt <= tx_cnt + 1;
        end
      end else if (uart_en) begin
        tx_flag <= 1;
        tx_cnt <= 0;
        tx_data <= uart_din;
      end
    end
  end
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_txd <= 0;
    end else begin
      if (tx_flag) begin
        if (tx_cnt == 0) begin
          uart_txd <= 1;
        end else if (tx_cnt == 1) begin
          uart_txd <= tx_data[0];
        end else if (tx_cnt == 2) begin
          uart_txd <= tx_data[1];
        end else if (tx_cnt == 3) begin
          uart_txd <= tx_data[2];
        end else if (tx_cnt == 4) begin
          uart_txd <= tx_data[3];
        end else if (tx_cnt == 5) begin
          uart_txd <= tx_data[4];
        end else if (tx_cnt == 6) begin
          uart_txd <= tx_data[5];
        end else if (tx_cnt == 7) begin
          uart_txd <= tx_data[6];
        end else if (tx_cnt == 8) begin
          uart_txd <= tx_data[7];
        end
      end
    end
  end
endmodule

