    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );
reg [1:0] cnt = 2'b00;
    reg sync = 1'b0;
    always @(posedge clk) begin
        if (toggle_en) begin
            if (opMode) begin
                if (cnt == cnt_n) begin
                    sync = 1'b1;
                    syncInOut = 1'b1;
                end else if (cnt == cnt_m) begin
                    sync = 1'b0;
                    syncInOut = 1'b0;
                end
            end else begin
                if (cnt == cnt_n) begin
                    sync = 1'b1;
                    syncInOut = 1'b1;
                end else if (cnt == cnt_m) begin
                    sync = 1'b0;
                    syncInOut = 1'b0;
                end
            end
        end
