module diffeq_paj_convert (Xinport, Yinport, Uinport, Aport, DXport, Xoutport, Youtport, Uoutport, CLK, reset);
    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
reg[31:0] x_var; 
    reg[31:0] y_var; 
    reg[31:0] u_var; 
    wire[31:0] temp; 
    always @(posedge CLK, posedge reset) begin
        if (reset == 1) begin
            x_var <= 0; 
            y_var <= 0; 
            u_var <= 0; 
        end else begin
            x_var <= x_var + temp; 
            y_var <= y_var + temp; 
            u_var <= u_var + temp; 
        end
    end
    always @(posedge CLK, posedge reset) begin
        if (reset == 1) begin
            temp <= 0; 
        end else begin
            temp <= (x_var - Aport) * (DXport / (x_var - Aport)); 
        end
    end
    assign Xoutport = x_var; 
    assign Youtport = y_var; 
    assign Uoutport = u_var; 
endmodule

