module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
);
reg [15:0] rd_compl_tag;
reg rd_compl_start;
reg rd_compl_done;
reg bm_tag_valid;
reg bm_tag;
reg [15:0] op_tag;
reg op_done;
assign OP_TAG = rd_compl_start ? rd_compl_tag : bm_tag;
assign OP_DONE = rd_compl_start ? rd_compl_done : bm_tag_valid;
always @(posedge CLK) begin
    if(RESET) begin
        rd_compl_tag <= 0;
        rd_compl_start <= 0;
        rd_compl_done <= 0;
        bm_tag_valid <= 0;
        bm_tag <= 0;
        op_tag <= 0;
        op_done <= 0;
    end else begin
        if(RD_COMPL_START) begin
            rd_compl_tag <= RD_COMPL_TAG;
            rd_compl_start <= 1;
            rd_compl_done <= 0;
            bm_tag_valid <= 0;
            bm_tag <= 0;
        end else if(RD_COMPL_DONE) begin
            rd_compl_start <= 0;
            rd_compl_done <= 1;
        end else if(BM_DONE) begin
            bm_tag_valid <= 1;
            bm_tag <= BM_TAG;
        end
        if(rd_compl_start) begin
            op_tag <= rd_compl_tag;
            op_done <= rd_compl_done;
        end else begin
            op_tag <= bm_tag;
            op_done <= bm_tag_valid;
        end
    end
end
endmodule

