module mips_alu(zero, result, alu_op, first_data, second_data, shamt);
output reg zero;					
	output reg [31:0] result;
	input [31:0] first_data;		
	input [31:0] second_data;		
	input [3:0] alu_op;				
	input [4:0] shamt;
reg [31:0] add_result, sub_result, and_result, or_result, nor_result, shift_result;
	reg [31:0] shift_amount;

	always @* begin
		case (alu_op)
			0: begin
				add_result = first_data + second_data;
				if (add_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			1: begin
				sub_result = first_data - second_data;
				if (sub_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			2: begin
				and_result = first_data & second_data;
				if (and_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			3: begin
				or_result = first_data | second_data;
				if (or_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			4: begin
				nor_result = ~(first_data | second_data);
				if (nor_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			5: begin
				shift_amount = shamt;
				shift_result = first_data << shift_amount;
				if (shift_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			6: begin
				shift_amount = shamt;
				shift_result = first_data >> shift_amount;
				if (shift_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
				end
			end
			7: begin
				shift_amount = shamt;
				shift_result = first_data >>> shift_amount;
				if (shift_result == 0) begin
					zero = 1;
				end else begin
					zero = 0;
