module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [1:0] index;
    reg empty_n, full_n;
    always @(posedge clk) begin
        if (aclr) begin
            empty_n <= 1'b1;
            full_n  <= 1'b0;
            index  <= 2'b00;
        end else begin
            if (write) begin
                if (empty_n) begin
                    mem[index] <= din;
                    index <= index + 1;
                    if (index == DEPTH-1) begin
                        empty_n <= 1'b0;
                    end
                end
            end
            if (read) begin
                if (full_n) begin
                    dout <= mem[index];
                    index <= index - 1;
                    if (index == 0) begin
                        full_n <= 1'b0;
                    end
                end
            end
        end
    end
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always @(posedge clk) begin
    if(timer == 1000000) begin
        if(btn_input == pre) begin
            btn_output <= btn_input;
        end
        timer <= 0;
        pre <= btn_input;
    end else begin
        timer <= timer + 1;
    end
end
endmodule

