module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter		divider = 100000;
reg [26:0] counter = 0;
always @(posedge Clock) begin
	if(MR) begin
		counter <= 0;
		Timeout <= 0;
	end else if(counter == divider) begin
		Timeout <= 1;
		counter <= 0;
	end else begin
		Timeout <= 0;
		counter <= counter + 1;
	end
end
endmodule

