module TopModule(
    input  y (6 bits),
    input  w,
    output Y1,
    output Y3
);

reg [1:0] Y2, Y4;

always @ (y, w) begin
    case (y[5:0])
        6'b000001: begin
            Y2 = 2'b00;
            Y4 = 2'b00;
        end
        6'b000010: begin
            Y2 = 2'b01;
            Y4 = 2'b00;
        end
        6'b000100: begin
            Y2 = 2'b10;
            Y4 = 2'b00;
        end
        6'b010000: begin
            Y2 = 2'b11;
            Y4 = 2'b00;
        end
        6'b100000: begin
            Y2 = 2'b00;
            Y4 = 2'b01;
        end
        default: begin
            Y2 = 2'b00;
            Y4 = 2'b00;
        end
    endcase
end

endmodule

