                end else begin
                    y <= 3'b001;
                end
            end
            3'b001: begin
                if (x == 1'b0) begin
                    y <= 3'b001;
                end else begin
                    y <= 3'b100;
                end
            end
            3'b010: begin
                if (x == 1'b0) begin
                    y <= 3'b010;
