                    y <= 3'b001;
                end else begin
                    y <= 3'b011;
                end
            end
            3'b100: begin
                if (x == 1'b0) begin
                    y <= 3'b100;
                end else begin
                    y <= 3'b100;
                end
            end
            default: begin
                y <= 3'b000;
            end
        endcase
    end
end

assign z = y[0];

