                next_state <= 0;
            end
            2: begin
                if (bump_left) begin
                    next_state <= 1;
                end else if (bump_right) begin
                    next_state <= 0;
                end else begin
                    next_state <= 2;
                end
            end
            default: begin
                next_state <= 0;
            end
        endcase
    end

    always @(posedge clk) begin
        case (state)
            0: begin
                output <= 0;
            end
            1: begin
                output <= 1;
            end
            2: begin
                output <= 0;
            end
            default: begin
                output <= 0;
            end
        endcase
    end

    always @(posedge clk) begin
        input <= {bump_left, bump_right};
