module TopModule(
    clk,
    areset,
    bump_left,
    bump_right,
    ground,
    dig,
    walk_left,
    walk_right,
    aaah,
    digging
);

reg [1:0] state;
reg falling;
reg [1:0] last_state;
reg [1:0] last_last_state;

always @(posedge clk) begin
    if (arst) begin
        state <= 0;
        falling <= 0;
    end else begin
        if (bump_left) begin
            state <= state + 1;
        end else if (bump_right) begin
            state <= state - 1;
        end
        if (ground) begin
            falling <= 0;
        end else if (falling == 0) begin
            falling <= 1;
        end
    end
end

always @(posedge clk) begin
    if (arst) begin
        last_state <= 0;
        last_last_state <= 0;
    end else begin
        last_last_state <= last_state;
        last_state <= state;
    end
end

always @(posedge clk) begin
    if (arst) begin
        aaah <= 0;
    end else if (falling) begin
        aaah <= 1;
    end else if (dig) begin
        aaah <= 0;
    end
end

always @(posedge clk) begin
    if (arst) begin
        digging <= 0;
    end else if (falling) begin
        digging <= 0;
    end else if (dig) begin
        digging <= 1;
    end
end

assign walk_left = (state == 0) ? 1 : 0;
assign walk_right = (state == 1) ? 1 : 0;
assign aaah = (last_last_state == 0 && last_state == 0 && state == 0) ? 1 : 0;
assign digging = (last_last_state == 0 && last_state == 0 && state == 0 && falling == 0) ? 1 : 0;

endmodule

